import{_ as r,a0 as p,w as u,s as l,ao as s,I as i,x as t,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux 有問必答：如何在 Linux 中改變默認的 Java 版本 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在 Linux 中改變默認的 Java 版本 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在 Linux 中改變默認的 Java 版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在 Linux 中改變默認的 Java 版本 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151105 Linux FAQs with Answers--How to change default Java version on Linux","title":"Linux 有問必答：如何在 Linux 中改變默認的 Java 版本","tag":"201511","desc":""},"relativePath":"201511/20151105 Linux FAQs with Answers--How to change default Java version on Linux.md","filePath":"[post].md"}'),d={name:"201511/20151105 Linux FAQs with Answers--How to change default Java version on Linux.md"};function v(x,a,J,m,f,L){const n=p("Link");return u(),l("div",null,[a[16]||(a[16]=s(`<h1 id="linux-有問必答-如何在-linux-中改變默認的-java-版本" tabindex="-1">Linux 有問必答：如何在 Linux 中改變默認的 Java 版本 <a class="header-anchor" href="#linux-有問必答-如何在-linux-中改變默認的-java-版本" aria-label="Permalink to “Linux 有問必答：如何在 Linux 中改變默認的 Java 版本”">​</a></h1><blockquote><p><strong>提問</strong>：當我嘗試在Linux中運行一個Java程序時，我遇到了一個錯誤。看上去像程序編譯所使用的Java版本與我本地的不同。我該如何在Linux上切換默認的Java版本？</p></blockquote><p>當Java程序編譯時，編譯環境會設置一個“target”變量來設置程序可以運行的最低Java版本。如果你Linux系統上運行的程序不能滿足最低的JRE版本要求，那麼你會在運行的時候遇到下面的錯誤。</p><pre><code>Exception in thread &quot;main&quot; java.lang.UnsupportedClassVersionError: com/xmodulo/hmon/gui/NetConf : Unsupported major.minor version 51.0
</code></pre><p>比如，程序在Java JRE 1.7下編譯，但是系統只有Java JRE 1.6。</p><p>要解決這個問題，你需要改變默認的Java版本到Java JRE 1.7或者更高（假設JRE已經安裝了）。</p><p>首先，試用下面的update-alternatives命令<strong>檢查你係統上可用的Java版本</strong>：</p><pre><code>$ sudo update-alternatives --display java
</code></pre><p><img src="https://c2.staticflickr.com/6/5663/22661333316_81fe1ab7da_c.jpg" alt=""></p><p>本例中，總共安裝了4個不同的Java版本：OpenJDK JRE 1.6、Oracle Java JRE 1.6、OpenJDK JRE 1.7 和 Oracle Java JRE 1.7。現在默認的Java版本是OpenJDK JRE 1.6。</p>`,10)),i("p",null,[a[1]||(a[1]=t("如果沒有安裝需要的Java JRE，你可以參考",-1)),e(n,{href:"http://ask.xmodulo.com/install-java-runtime-linux.html"},{default:o(()=>[...a[0]||(a[0]=[t("這些指導",-1)])]),_:1}),a[2]||(a[2]=t("來完成安裝。",-1))]),a[17]||(a[17]=s(`<p>現在有可用的候選版本，你可以用下面的命令在可用的Java JRE之間<strong>切換默認的Java版本</strong>：</p><pre><code>$ sudo update-alternatives --config java
</code></pre><p>看到提示的時候，選擇你想試用的Java版本。本例中，我們選擇Oracle Java JRE 1.7。</p><p><img src="https://c2.staticflickr.com/6/5651/22066181083_b9c4c5b676_c.jpg" alt=""></p><p>現在用下面的命令驗證默認的Java版本。</p><pre><code>$ java -version
</code></pre><p><img src="https://c1.staticflickr.com/1/634/22499411280_1d702a4101_c.jpg" alt=""></p><p>最後，如果你定義了JAVA_HOME環境變量，根據你設置的Java版本更新變量。</p><hr>`,9)),i("p",null,[a[4]||(a[4]=t("via: ",-1)),e(n,{href:"http://ask.xmodulo.com/change-default-java-version-linux.html"},{default:o(()=>[...a[3]||(a[3]=[t("http://ask.xmodulo.com/change-default-java-version-linux.html",-1)])]),_:1})]),i("p",null,[a[8]||(a[8]=t("作者：",-1)),e(n,{href:"http://ask.xmodulo.com/author/nanni"},{default:o(()=>[...a[5]||(a[5]=[t("Dan Nanni",-1)])]),_:1}),a[9]||(a[9]=t(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:o(()=>[...a[6]||(a[6]=[t("geekpi",-1)])]),_:1}),a[10]||(a[10]=t(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...a[7]||(a[7]=[t("wxy",-1)])]),_:1})]),i("p",null,[a[13]||(a[13]=t("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[11]||(a[11]=[t("LCTT",-1)])]),_:1}),a[14]||(a[14]=t(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...a[12]||(a[12]=[t("Linux中國",-1)])]),_:1}),a[15]||(a[15]=t(" 榮譽推出",-1))])])}const C=r(d,[["render",v]]);export{_ as __pageData,C as default};
